<section class="panel"><div class="panel-heading"><h2><?= e(t('Purchase register')) ?></h2><span class="muted"><?= e(t('{count} records',['count'=>$count])) ?></span></div>
<?php require __DIR__.'/partials/list-filters.php'; ?>
<div class="table-wrap"><table><thead><tr><th><?= e(t('Voucher / date')) ?></th><th><?= e(t('Supplier')) ?></th><th><?= e(t('Warehouse / rice type')) ?></th><th class="number"><?= e(t('Quantity (တင်း)')) ?></th><th class="number"><?= e(t('Weight (ပေါင်)')) ?></th><th class="number"><?= e(t('Price / တင်း')) ?></th><th class="number"><?= e(t('Amount (MMK)')) ?></th><th class="table-actions"><?= e(t('Actions')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['reference']) ?></strong><small><?= e($r['purchased_on']) ?></small></td><td><?= e($r['supplier']) ?></td><td><?= e($r['warehouse']) ?><small><?= e($r['rice']) ?></small><?php if($r['item_count']>1): ?><small><?= e(t('{count} items',['count'=>$r['item_count']])) ?></small><?php endif; ?></td><td class="number"><?= e(num($r['quantity'])) ?></td><td class="number"><?= $r['weight_lb'] !== null ? e(num($r['weight_lb'])) : '—' ?></td><td class="number"><?= $r['item_count']==1?e(money($r['unit_price'])):t('Mixed prices') ?></td><td class="number"><strong><?= e(money($r['amount'])) ?></strong></td><td class="table-actions"><div class="actions"><a class="button small" href="<?= e(url('purchase/'.$r['id'])) ?>"><?= e(t('Details')) ?></a><a class="button small" href="<?= e(url('voucher/'.$r['id'])) ?>"><?= e(t('View / Print')) ?></a><?php if(can('purchases.edit')): ?><a class="button small" href="<?= e(url('purchase/'.$r['id'].'/edit')) ?>"><?= e(t('Edit')) ?></a><?php endif; ?><?php if(can('purchases.delete')): ?><form method="post" action="<?= e(url('purchase/'.$r['id'].'/delete')) ?>" data-confirm="<?= e(t('Delete this purchase and reverse its stock effects? This cannot be undone.')) ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($r['version']) ?>"><button class="button small danger" type="submit"><?= e(t('Delete')) ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="empty"><?= e(t('No purchases found. Your recorded purchases will appear here.')) ?></td></tr><?php endif; ?></tbody></table></div>
<?php require __DIR__.'/partials/pagination.php'; ?></section>
